// Grafana's alerting already knows things nothing else here does -- backup
// staleness, targets down, the rules in grafana.nix -- but it only ever said
// them into Discord and email. Both are places you read later, which makes
// them the wrong shape for "a backup has not run in two days".
//
// This translates Grafana's unified-alerting webhook into the spine's format.
// It is a translator and nothing more: no thresholds, no opinions about what
// matters. Grafana decides what fires; the spine decides whether it is worth
// interrupting someone.

const SOURCE = "grafana";

// Grafana labels severity freely and its own rules here use "warning". Map
// what is recognised and fall back to warning rather than guessing upward:
// an unknown label should not invent a critical page.
const SEVERITY = {
  critical: "critical",
  error: "critical",
  warning: "warning",
  info: "info",
  none: "info",
};

const payload = $input.first().json.body ?? $input.first().json;
const alerts = Array.isArray(payload?.alerts) ? payload.alerts : [];

if (alerts.length === 0) {
  // A webhook that fires with no alerts is Grafana misconfigured, not silence.
  // Saying so is cheap; swallowing it would look exactly like "nothing wrong".
  return [
    {
      json: {
        source: SOURCE,
        severity: "warning",
        title: "alert webhook carried no alerts",
        message: `Grafana POSTed a payload with an empty or missing \`alerts\` array.\n\n${JSON.stringify(payload).slice(0, 400)}`,
        fingerprint: `${SOURCE}:empty-payload`,
      },
    },
  ];
}

return alerts.map((alert) => {
  const labels = alert.labels ?? {};
  const annotations = alert.annotations ?? {};
  const resolved = (alert.status ?? payload.status) === "resolved";

  const title = labels.alertname ?? payload.title ?? "unnamed Grafana alert";

  // Prefer the human sentence the rule author wrote; valueString is the raw
  // series and is only useful when nobody wrote one.
  const body =
    annotations.summary ||
    annotations.description ||
    alert.valueString ||
    "Grafana gave no summary for this rule.";

  // Grafana's own fingerprint is stable for the same rule and label set, which
  // is exactly what the spine deduplicates on -- better than anything that
  // could be reconstructed from the title here.
  const fingerprint = alert.fingerprint
    ? `${SOURCE}:${alert.fingerprint}`
    : `${SOURCE}:${title}`;

  return {
    json: {
      source: SOURCE,
      severity: SEVERITY[String(labels.severity ?? "").toLowerCase()] ?? "warning",
      title,
      message: body,
      fingerprint,
      resolved,
      url: alert.silenceURL || alert.dashboardURL || alert.generatorURL || payload.externalURL || null,
    },
  };
});
